111	func (g *Generator) Generate(ctx context.Context, input GenerateInput) ([]MemoryRecord, GenerationStats, *llmcli.UsageInfo, error) {
112		if g.Runner == nil {
113			g.Runner = &llmcli.Runner{}
114		}
115	
116		if input.MaxRecords <= 0 {
117			input.MaxRecords = DefaultMaxRecords
118		}
119	
120		raw, usage, err := g.Runner.Execute(ctx, BuildPrompt(input))
121		if err != nil {
122			return nil, GenerationStats{}, nil, fmt.Errorf("execute memory-loop prompt: %w", err)
123		}
124	
125		var resp generateResponse
126		if err := json.Unmarshal([]byte(raw), &resp); err != nil {
127			return nil, GenerationStats{}, nil, fmt.Errorf("parse memory-loop JSON: %w", err)
128		}
129	
130		records, stats := buildGeneratedRecordsDetailed(resp, input, time.Now().UTC())
131		return records, stats, usage, nil
132	}
133	
134	func buildGeneratedRecords(resp generateResponse, input GenerateInput, now time.Time) []MemoryRecord {
135		records, _ := buildGeneratedRecordsDetailed(resp, input, now)
136		return records
137	}
138	
139	func buildGeneratedRecordsDetailed(resp generateResponse, input GenerateInput, now time.Time) ([]MemoryRecord, GenerationStats) {
140		orderedKeys := make([]string, 0, len(resp.Records))
141		bestByKey := make(map[string]generatedCandidate)
142		stats := GenerationStats{}
143		for _, item := range resp.Records {
144			title := cleanGeneratedText(item.Title)
145			body := cleanGeneratedText(item.Body)
146			if title == "" || body == "" {
147				continue
148			}
149			kind := item.Kind
150			if kind == "" {
151				kind = KindRepoRule
152			}
153			confidence := normalizeConfidence(item.Confidence)
154			strength := clamp(item.Strength, 1, 5)
155			if confidence == confidenceLow || strength < 3 {
156				stats.FilteredWeakCount++
157				continue
158			}
159			if isGenericGeneratedCandidate(title, body) {
160				stats.FilteredGenericCount++
161				continue
162			}
163	
164			record := MemoryRecord{
165				ID:               MakeRecordID(kind, title),
166				Kind:             kind,
167				Title:            title,
168				Body:             body,
169				SkillName:        strings.TrimSpace(item.SkillName),
170				SkillPath:        strings.TrimSpace(item.SkillPath),
171				Why:              strings.TrimSpace(item.Why),
172				Evidence:         trimSlice(item.Evidence, 3),
173				SourceSessionIDs: trimSlice(item.SourceSessionIDs, input.SourceWindow),
174				Confidence:       confidence,
175				Strength:         strength,
176				Status:           StatusCandidate,
177				Origin:           OriginGenerated,
178				Fingerprint:      FingerprintForRecord(kind, title, body),
179				CreatedAt:        now,
180				UpdatedAt:        now,
181			}
182			if !passesReviewDerivedGate(record, input.Analysis) {
183				stats.FilteredGenericCount++
184				continue
185			}
186	
187			key := normalizedGeneratedCandidateKey(kind, title, body)
188			next := generatedCandidate{
189				record:            record,
190				confidenceRank:    confidenceRank(confidence),
191				specificityScore:  generatedSpecificityScore(title, body),
192				normalizedContent: len(normalizeGeneratedText(title)) + len(normalizeGeneratedText(body)),
193			}
194			existing, ok := bestByKey[key]
195			if !ok {
196				orderedKeys = append(orderedKeys, key)
197				bestByKey[key] = next
198				continue
199			}
200			stats.DedupedCount++
201			if shouldReplaceGeneratedCandidate(existing, next) {
202				bestByKey[key] = next
203			}
204		}
205	
206		records := make([]MemoryRecord, 0, len(orderedKeys))
207		for _, key := range orderedKeys {
208			records = append(records, bestByKey[key].record)
209			if len(records) >= input.MaxRecords {
210				break
211			}
212		}
213	
214		return records, stats
215	}
