329	func cleanGeneratedText(value string) string {
330		return strings.Join(strings.Fields(strings.TrimSpace(value)), " ")
331	}
332	
333	func normalizedGeneratedCandidateKey(kind Kind, title, body string) string {
334		return strings.Join([]string{
335			string(kind),
336			normalizeGeneratedText(title),
337			normalizeGeneratedText(body),
338		}, "|")
339	}
340	
341	func normalizeGeneratedText(value string) string {
342		value = strings.ToLower(cleanGeneratedText(value))
343		var b strings.Builder
344		b.Grow(len(value))
345		lastSpace := false
346		for _, r := range value {
347			if unicode.IsLetter(r) || unicode.IsDigit(r) {
348				b.WriteRune(r)
349				lastSpace = false
350				continue
351			}
352			if !lastSpace {
353				b.WriteByte(' ')
354				lastSpace = true
355			}
356		}
357		return strings.TrimSpace(strings.Join(strings.Fields(b.String()), " "))
358	}
359	
360	func passesReviewDerivedGate(record MemoryRecord, analysis improve.PatternAnalysis) bool {
361		if len(analysis.ReviewDerivedRules) == 0 {
362			return true
363		}
364		for _, signal := range analysis.ReviewDerivedRules {
365			if generatedMatchesReviewEvidence(record, signal) {
366				return false
367			}
368		}
369	
370		signal, score := bestMatchingReviewDerivedRule(record, analysis.ReviewDerivedRules)
371		if signal == nil || score < 0.50 {
372			return true
373		}
374		return signal.Count >= 2 || signal.Strong
375	}
376	
377	func bestMatchingReviewDerivedRule(record MemoryRecord, signals []improve.ReviewDerivedRuleSignal) (*improve.ReviewDerivedRuleSignal, float64) {
378		bestScore := 0.0
379		var best *improve.ReviewDerivedRuleSignal
380		for i := range signals {
381			score := logicalRuleSimilarity(
382				MemoryRecord{Title: record.Title, Body: record.Body},
383				MemoryRecord{Title: signals[i].Rule},
384			)
385			if score > bestScore {
386				bestScore = score
387				best = &signals[i]
388			}
389		}
390		return best, bestScore
391	}
392	
393	func generatedMatchesReviewEvidence(record MemoryRecord, signal improve.ReviewDerivedRuleSignal) bool {
394		title := normalizeGeneratedText(record.Title)
395		body := normalizeGeneratedText(record.Body)
396		combined := normalizeGeneratedText(record.Title + " " + record.Body)
397		for _, evidence := range signal.Evidence {
398			normalizedEvidence := normalizeGeneratedText(evidence)
399			if normalizedEvidence == "" {
400				continue
401			}
402			if normalizedEvidence == title || normalizedEvidence == body || normalizedEvidence == combined {
403				return true
404			}
405			if strings.Contains(body, normalizedEvidence) || strings.Contains(combined, normalizedEvidence) {
406				return true
407			}
408			if strings.Contains(normalizedEvidence, body) || strings.Contains(normalizedEvidence, combined) {
409				return true
410			}
411		}
412		return false
413	}
414	
415	func isGenericGeneratedCandidate(title, body string) bool {
416		combined := normalizeGeneratedText(title + " " + body)
417		if combined == "" {
418			return true
419		}
420		if hasGeneratedSpecificityMarker(title, body) {
421			return false
422		}
423		for _, phrase := range genericAdvicePhrases {
424			if strings.Contains(combined, phrase) {
425				return true
426			}
427		}
428		return false
429	}
430	
431	func hasGeneratedSpecificityMarker(title, body string) bool {
432		normalized := normalizeGeneratedText(title + " " + body)
433		rawLower := strings.ToLower(title + " " + body)
434		for _, marker := range generatedSpecificityMarkers {
435			if strings.Contains(rawLower, marker) || strings.Contains(normalized, marker) {
436				return true
437			}
438		}
439		return false
440	}
441	
442	func generatedSpecificityScore(title, body string) int {
443		normalized := normalizeGeneratedText(title + " " + body)
444		score := len(strings.Fields(normalized))
445		for _, marker := range generatedSpecificityMarkers {
446			if strings.Contains(normalized, marker) || strings.Contains(strings.ToLower(title+" "+body), marker) {
447				score += 3
448			}
449		}
450		return score
451	}
452	
453	func shouldReplaceGeneratedCandidate(existing, next generatedCandidate) bool {
454		switch {
455		case next.confidenceRank != existing.confidenceRank:
456			return next.confidenceRank > existing.confidenceRank
457		case next.record.Strength != existing.record.Strength:
458			return next.record.Strength > existing.record.Strength
459		case next.specificityScore != existing.specificityScore:
460			return next.specificityScore > existing.specificityScore
461		case next.normalizedContent != existing.normalizedContent:
462			return next.normalizedContent > existing.normalizedContent
463		default:
464			return false
465		}
466	}
467	
468	func MakeRecordID(kind Kind, title string) string {
469		base := strings.ToLower(strings.TrimSpace(title))
470		var b strings.Builder
471		lastDash := false
472		for _, r := range base {
473			switch {
474			case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
475				b.WriteRune(r)
476				lastDash = false
477			default:
478				if !lastDash {
479					b.WriteByte('-')
480					lastDash = true
481				}
482			}
483		}
484		slug := strings.Trim(b.String(), "-")
485		if slug == "" {
486			slug = defaultMemorySlug
487		}
488		return fmt.Sprintf("%s-%s", kind, slug)
489	}
490	
491	func trimSlice[T any](items []T, limit int) []T {
492		if limit <= 0 || len(items) <= limit {
493			return items
494		}
495		return items[:limit]
496	}
497	
498	func normalizeConfidence(value string) string {
499		switch strings.ToLower(strings.TrimSpace(value)) {
500		case confidenceHigh, confidenceMedium, confidenceLow:
501			return strings.ToLower(strings.TrimSpace(value))
502		default:
503			return confidenceMedium
504		}
505	}
506	
507	func confidenceRank(value string) int {
508		switch value {
509		case confidenceHigh:
510			return 3
511		case confidenceMedium:
512			return 2
513		case confidenceLow:
514			return 1
515		default:
516			return 0
517		}
518	}
519	
520	func clamp(value, lo, hi int) int {
521		if value < lo {
522			return lo
523		}
524		if value > hi {
525			return hi
526		}
527		return value
528	}
